<script>
  import http from '../../assets/js/http'
  export default {
    data() {
      return {
        timmer: 0,
        loading: true,
        is_douyu: false,
        default_width: '80%',
        douyu_url: '',
        detail_visible: false,
        recordData: {},
        tableData: [],
        specific_bet_info: [],
        play_video_url: '',
        replay_data: [],
        game_id: 0,
        game_type: 0,
        small_type: 0,
        cards: [],
        lock_bet_list: [6002, 6003, 6011, 6012, 6013, 6501, 6502, 6504, 6507, 6016, 6017, 6022],
        left_cards: {},
        public_cards: {},
        right_cards: {},
        banker: {}
      }
    },
    computed: {
    },
    methods: {
      rowStyle({ row, rowIndex }) {
        var local_user_id = Lockr.get('user_id')
        if (row.user_id == local_user_id) {
          return 'background: pink'
        }
      },
      showButton() {
        var user_agent = navigator.userAgent.toLowerCase()
        var is_app = false
        if (user_agent.indexOf('browser_type/android_app') != -1) {
          is_app = true
        }
        return (this.game_type == 304 || this.game_type == 305 || this.game_id == 6702) // && is_app
      },
      // 显示图片类型
      showPic() {
        return this.game_id != 6508 || this.game_id != 6015 || this.game_id != 6704 || this.game_id != 6016 || this.game_id != 6706 || this.game_id != 6707 || this.game_id != 6708
      },
      // 录像回放
      playBack() {
        if (this.play_video_url.length > 0) {
          window.open(this.play_video_url)
        }
      },
      // 是否显示庄/闲
      showBanker() {
        return this.small_type == 30103 || this.small_type == 30104 || this.small_type == 30106
      },
      // 是否显示抢庄倍数
      showScrambleMultiple() {
        return this.small_type == 30104
      },
      // 是否显示下注倍数
      showBetMultiple() {
        // 6714押宝抢庄牛牛没有下注倍数
        if (this.small_type === 30104 && this.game_id === 6714) return
        return this.small_type == 30102 || this.small_type == 30103 || this.small_type == 30104
      },
      // 显示手牌
      showHandcard() {
        return this.small_type == 30106 || this.small_type == 30107
      },
      // 区域下注是否显示牌/牌型字段
      showCardsType() {
        return this.small_type == 30202
      },
      // 是否显示结果
      showResult() {
        return this.small_type != 30106 && this.small_type != 30107 && this.small_type
      },
      // 打牌类详情表字段
      showHoe() {
        return this.small_type == 30402
      },
      showBaseChips() {
        return this.small_type == 30401
      },
      timeLabel() {
        let utc = Lockr.get('timezone')
        return utc == -4 ? this.$t('message.usa_time') : ''
      },
      open() {
        this.timmer = setTimeout(() => {
          if (this.loading) {
            bus.$message({
              message: this.$t('message.request_timeout'),
              duration: 0,
              type: 'warning'
            })
          }
        }, 5000)
        this.detail_visible = true
        this.recordData = Lockr.get('chess_detail')
        this.apiGet(this.is_douyu ? this.douyu_url : this.recordData.dt_new_url).then((res) => {
          this.handelResponse(res, (data) => {
            if (this.is_douyu) {
              data = data.data
            }
            this.game_id = data.info.game_id
            this.game_type = data.info.game_type
            this.small_type = data.info.small_type
            this.tableData = [{ key1: '', value1: '', key2: '', value2: '' },
            { key1: '', value1: '', key2: '', value2: '' },
            { key1: '', value1: '', key2: '', value2: '' },
            { key1: '', value1: '', key2: '', value2: '' },
            { key1: '', value1: '', key2: '', value2: '' },
            { key1: '', value1: '', key2: '', value2: '' }]
            // key
            this.tableData[0].key1 = this.$t('message.game_time') + this.timeLabel()
            this.tableData[0].key2 = this.$t('message.room_type')
            this.tableData[1].key1 = this.$t('message.game_number')
            this.tableData[1].key2 = this.$t('message.room_rccess')
            this.tableData[2].key1 = this.$t('message.game_round_id')
            this.tableData[2].key2 = this.$t('message.room_bet')
            this.tableData[3].key1 = this.$t('message.game_name')
            // value
            this.tableData[0].value1 = data.info.time
            this.tableData[0].value2 = data.info.room_type
            this.tableData[1].value1 = data.info.id
            this.tableData[1].value2 = data.info.min_enter_chips == 0 ? data.info.min_enter_chips : (data.info.min_enter_chips / 100).toFixed(2)
            this.tableData[2].value1 = data.info.round_id
            if (this.small_type == 30106) {
              this.tableData[2].value2 = (data.info.base_chips[0] / 100).toFixed(2).toString() + '~' + (data.info.base_chips[1] / 100).toFixed(2).toString()
            } else {
              this.tableData[2].value2 = data.info.base_chips == 0 ? data.info.base_chips : (data.info.base_chips / 100).toFixed(2)
            }
            this.tableData[3].value1 = data.info.game_name
            if (this.lock_bet_list.indexOf(this.game_id) == -1) {
              if (this.small_type == 30194) {
                this.tableData.splice(5, 1)
                this.tableData[3].key2 = this.$t('message.locked_money')
                this.tableData[3].value2 = (data.info.lock_chips / 100).toFixed(2)
                this.tableData[4].key1 = this.$t('message.total_revenue')
                this.tableData[4].value1 = (data.info.all_profit / 100).toFixed(2)
              } else if (this.small_type == 30201) {
                if (this.game_id === 6706 || this.game_id === 6707 || this.game_id === 6708 || this.game_id === 6709 || this.game_id === 6710 || this.game_id === 6021) { // 猜色球/wingo/AndarBahar/越南鱼虾蟹
                  this.tableData[1].key2 = this.$t('message.total_bets')
                  this.tableData[1].value2 = (this.recordData.all_bets / 100).toFixed(2)
                  this.tableData[2].key2 = this.$t('message.total_revenue')
                  this.tableData[2].value2 = (data.info.all_profit / 100).toFixed(2)
                  this.tableData.splice(5, 1)
                  this.tableData.splice(4, 1)

                  if (this.game_id === 6707 || this.game_id === 6708) {
                    this.tableData[0].key2 = this.$t('message.game_name')
                    this.tableData[0].value2 = data.info.game_name
                    this.tableData.splice(3, 1)
                  }
                }
              } else {
                this.tableData.splice(5, 1)
                if (this.game_type == 302) {
                  this.tableData[3].key2 = this.$t('message.total_bets')
                  this.tableData[3].value2 = (this.recordData.all_bets / 100).toFixed(2)
                  this.tableData[4].key1 = this.$t('message.total_revenue')
                  this.tableData[4].value1 = (data.info.all_profit / 100).toFixed(2)
                } else {
                  this.tableData.splice(4, 1)
                  this.tableData[3].key2 = this.$t('message.total_revenue')
                  this.tableData[3].value2 = (data.info.all_profit / 100).toFixed(2)
                }
              }
            } else {
              if (this.game_type == 302) {
                this.tableData[3].key2 = this.$t('message.locked_money')
                this.tableData[3].value2 = (data.info.lock_chips / 100).toFixed(2)
                this.tableData[4].key1 = ''
                this.tableData[4].value1 = ''
                this.tableData[4].key2 = this.$t('message.total_bets')
                this.tableData[4].value2 = (this.recordData.all_bets / 100).toFixed(2)
                this.tableData[5].key1 = ''
                this.tableData[5].value1 = ''
                this.tableData[5].key2 = this.$t('message.total_revenue')
                this.tableData[5].value2 = (data.info.all_profit / 100).toFixed(2)
                if (this.small_type == 30201 && this.game_id != 6016) {
                  this.tableData[3].key2 = this.$t('message.total_revenue')
                  this.tableData[3].value2 = (data.info.all_profit / 100).toFixed(2)
                  this.tableData.splice(4, 1)
                  this.tableData.splice(4, 1)
                }
              } else {
                this.tableData.splice(5, 1)
                this.tableData[3].key2 = this.$t('message.locked_money')
                this.tableData[3].value2 = (data.info.lock_chips / 100).toFixed(2)
                this.tableData[4].key1 = ''
                this.tableData[4].value1 = ''
                this.tableData[4].key2 = this.$t('message.total_revenue')
                this.tableData[4].value2 = (data.info.all_profit / 100).toFixed(2)
              }
            }

            switch (this.game_type) {
              case 301:
              case 304:
              case 305:
                this.specific_bet_info = data.info.user_list
                break
              case 302:
                this.specific_bet_info = data.info.seats
                break
            }
            switch (this.small_type) {
              case 30201:
                this.banker = data.info.banker
                break
              case 30202:
              case 30203:
                this.banker = data.info.banker
                break
              case 30204:
                this.left_cards = data.info.banker.card.left
                this.public_cards = data.info.banker.card.public
                this.right_cards = data.info.banker.card.right
                break
              case 30401:
              case 30402:
              case 30403:
              case 30501:
              case 30404:
                this.replay_data = data.info.replay_data
                this.play_video_url = data.play_video_url
                break
            }
            this.loading = false
          })
        })
      },
      close() {
        clearTimeout(this.timmer)
        Lockr.rm('chess_detail')
        this.loading = true
        this.game_type = 0
        this.small_type = 0
        this.detail_visible = false
        this.specific_bet_info = []
        this.cards = []
        this.tableData = []
        this.left_cards = {}
        this.public_cards = {}
        this.right_cards = {}
      }
    },
    created() {
      let data = this.$route.query
      if (JSON.stringify(data) != '{}') {
        document.title = this.$t('message.game_details')
        this.is_douyu = true
        this.default_width = '100%'
        if (data.token) {
          window.axios.defaults.headers.Authorization = 'Bearer ' + data.token
        }
        if (data.token && data.round_id && data.agent_id) {
          this.douyu_url = _g.dyUrl() + '?round_id=' + data.round_id + '&agent_id=' + data.agent_id
        }

        this.open()
      }
    },
    mixins: [http]
  }
</script>


